// Arkon Quality Steering Cell - intake logic.
// Validates the event contract (events/arkon_event_schema.json),
// deduplicates, and builds the incident record.
const REQUIRED = ["event_id", "event_time", "source_module", "business_domain", "risk_type", "risk_score", "priority", "summary", "evidence", "context_origin", "recommended_action", "status"];
const PRIORITIES = ["P1", "P2", "P3", "P4"];

const event = $json.body ?? $json;
const errors = [];
for (const f of REQUIRED) {
  if (!(f in event)) errors.push(`missing field: ${f}`);
}
if (!errors.length) {
  if (!PRIORITIES.includes(event.priority)) errors.push(`bad priority: ${event.priority}`);
  if (typeof event.risk_score !== "number" || event.risk_score < 0 || event.risk_score > 1) errors.push("bad risk_score");
  if (!event.evidence || typeof event.evidence !== "object") errors.push("bad evidence");
  if (event.operational_context && event.operational_context.context_origin !== "simulated") errors.push("operational_context must be labelled simulated");
}
if (errors.length) {
  return { json: { valid: false, alert: false, duplicate: false, errors, event_id: event.event_id ?? null } };
}

// Dedup: the same evidence record + priority within 24 h creates no second incident.
// Note: static data persists for production executions of an ACTIVE workflow.
const store = $getWorkflowStaticData("global");
store.seen = store.seen || {};
store.counter = store.counter || 0;
const key = `${event.evidence.record_id}|${event.priority}`;
const now = Date.now();
const DEDUP_MS = 24 * 60 * 60 * 1000;
// Drop entries that fell out of the dedup window, so static data
// does not grow without bound over the life of the workflow.
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] >= DEDUP_MS) delete store.seen[k];
}
const isDuplicate = Boolean(store.seen[key] && (now - store.seen[key]) < DEDUP_MS);
store.seen[key] = now;

let incident = null;
if (!isDuplicate) {
  store.counter += 1;
  incident = {
    incident_id: `ARK-INC-${String(store.counter).padStart(5, "0")}`,
    created_at: new Date().toISOString(),
    status: "new",
    priority: event.priority,
    source_module: event.source_module,
    business_domain: event.business_domain,
    summary: event.summary,
    recommended_action: event.recommended_action,
    assigned_role: event.operational_context?.assigned_role ?? "Quality Steering Cell",
    assigned_to: event.operational_context?.assigned_to ?? "unassigned",
    escalation_contact: event.operational_context?.escalation_contact ?? null,
    event: event,
  };
}

// Telegram parses the message body, so every value that comes out of an event has
// to be escaped before it meets the markup. This is HTML rather than Markdown
// because HTML has exactly three characters to escape and none of them can be left
// unmatched by accident. Legacy Markdown treats an underscore as an italic marker:
// the single underscore in a record id like NEU-INCLUSION_244 made Telegram reject
// the whole message with "can't parse entities", after the incident had already
// been written and its id consumed, and the caller saw HTTP 200 with an empty body.
// CMAPSS and Scania identifiers carry no marker characters, which is the only
// reason this branch appeared to work: it had never been sent anything else.
const esc = (value) => String(value === null || value === undefined ? "" : value)
  .replace(/&/g, "&amp;")
  .replace(/</g, "&lt;")
  .replace(/>/g, "&gt;");

// The card is step 4 of the process and the operator's controls are step 5, so the
// card carries a link that opens the cockpit's Steering Cell page on this one
// incident. The base is an address rather than a host name because the phone that
// receives the card resolves neither `AK2101` nor the tailnet name; set
// ARKON_COCKPIT_URL in n8n's environment to point it somewhere else.
let cockpitBase = "http://192.168.178.100:8303";
try {
  if (typeof $env !== "undefined" && $env.ARKON_COCKPIT_URL) {
    cockpitBase = String($env.ARKON_COCKPIT_URL);
  }
} catch (err) {
  // Env access is blocked in some n8n configurations. The default above stands.
}
cockpitBase = cockpitBase.replace(/\/+$/, "");
const cockpitLink = (incidentId) =>
  cockpitBase + "/steering_cell?incident=" + encodeURIComponent(incidentId);

let alertText = null;
if (incident) {
  alertText = [
    "\u{1F6A8} <b>Arkon Quality Steering Cell</b>",
    "<b>" + esc(incident.priority) + "</b> incident <b>" + esc(incident.incident_id) + "</b>",
    "",
    esc(incident.summary),
    "",
    "Assigned: " + esc(incident.assigned_to) + " (" + esc(incident.assigned_role) + ")",
    "Action: " + esc(incident.recommended_action),
    "Event: <code>" + esc(event.event_id) + "</code>",
    "",
    '<a href="' + cockpitLink(incident.incident_id) + '">Open in the Steering Cell</a>',
  ].join("\n");
}

return {
  json: {
    valid: true,
    duplicate: isDuplicate,
    alert: !isDuplicate && ["P1", "P2"].includes(event.priority),
    incident,
    incident_json: incident ? JSON.stringify(incident) : null,
    // One ready JSONL line, newline included, written by the file node.
    incident_jsonl: incident ? JSON.stringify(incident) + "\n" : null,
    event_id: event.event_id,
    priority: event.priority,
    summary: event.summary,
    // The whole alert body, escaped and ready. The Telegram node sends this one
    // field and interpolates nothing of its own.
    alert_text: alertText,
  },
};
